import { Router } from 'express';
import { DeliveryMethod } from '@shopify/shopify-api';
import { shopify } from '../shopify.js';
import { appUninstalledHandler } from '../webhooks/appUninstalled.js';

const router = Router();

// In shopify-app-express v5, handlers are passed directly to processWebhooks()
// which returns an array of RequestHandler[] — spread them into the route.
// Raw body is applied in app.ts for this path so HMAC verification works.
router.post(
  '/',
  ...shopify.processWebhooks({
    webhookHandlers: {
      APP_UNINSTALLED: {
        deliveryMethod: DeliveryMethod.Http,
        callbackUrl: '/webhooks',
        callback: appUninstalledHandler,
      },
    },
  }),
);

export default router;
